const modal = {
  previousFocus: null,
  open() {
    if (!el.helpModal || !el.modalClose) return;
    modal.previousFocus = document.activeElement;
    el.helpModal.classList.add('active');
    el.modalClose.focus();
    document.body.style.overflow = 'hidden';
  },
  close() {
    if (!el.helpModal) return;
    el.helpModal.classList.remove('active');
    document.body.style.overflow = '';
    modal.previousFocus?.focus?.();
  }
};

const toggleActive = () => {
  state.active = !state.active;
  haptic(10);
  applyState();
  storage.save();
};

const cycleColor = () => {
  if (animatingColorShift || !el.circle) return;
  animatingColorShift = true;
  state.colorMode = (state.colorMode + 1) % COLORS.length;
  state.active = true;
  haptic(20);
  el.circle.classList.add('color-shifting');
  const timeoutId = setTimeout(() => {
    el.circle?.classList.remove('color-shifting');
    animatingColorShift = false;
  }, CONFIG.colorShiftDuration);
  applyState();
  storage.save();
  return timeoutId;
};

const randomizeColor = () => {
  if (animatingColorShift || !el.circle) return;
  animatingColorShift = true;
  state.colorMode = getRandomColorMode();
  state.active = true;
  haptic([20, 10, 20]);
  el.circle.classList.add('color-shifting');
  const timeoutId = setTimeout(() => {
    el.circle?.classList.remove('color-shifting');
    animatingColorShift = false;
  }, CONFIG.colorShiftDuration);
  applyState();
  storage.save();
  return timeoutId;
};

const resetState = () => {
  state = { active: false, colorMode: 0 };
  haptic(10);
  applyState();
  storage.save();
};

const handleTouchEnd = () => {
  tapCount++;
  haptic(10);
  clearTimeout(tapTimeout);

  if (tapCount === 1) {
    tapTimeout = setTimeout(() => {
      if (tapCount === 1) {
        toggleActive();
      }
      tapCount = 0;
    }, CONFIG.tapDelay);
  } else if (tapCount >= 2) {
    tapCount = 0;
    cycleColor();
  }
};

const keyHandlers = {
  ' ': toggleActive,
  'enter': toggleActive,
  'escape': resetState,
  'c': cycleColor,
  'x': randomizeColor,
  'r': resetState,
  '?': modal.open
};

const handleKeyDown = (e) => {
  const key = e.key.toLowerCase();
  const handler = keyHandlers[key];
  if (!handler) return;

  const now = Date.now();
  if (now - lastKeyTime < CONFIG.keyDebounce) return;

  e.preventDefault();
  try {
    handler();
    lastKeyTime = now;
  } catch (err) {
    console.error('Keyboard handler error:', err);
  }
};

const handleModalKeyDown = (e) => {
  if (!el.helpModal?.classList.contains('active')) return;

  if (e.key === 'Escape') {
    e.preventDefault();
