const updateClasses = () => {
  if (!el.circle) return;

  el.circle.classList.toggle('active', state.active);
  el.circle.setAttribute('aria-pressed', state.active.toString());
  el.circle.setAttribute('aria-expanded', (state.colorMode > 0).toString());

  const oldColorClass = Array.from(el.circle.classList).find(cls => cls.startsWith('color-mode-'));
  const newColorClass = getColorClass(state.colorMode);

  if (oldColorClass !== newColorClass) {
    if (oldColorClass) {
      el.circle.classList.remove(oldColorClass);
    }
    if (newColorClass !== 'default') {
      el.circle.classList.add(newColorClass);
    }
  }
};

const updateUI = () => {
  const hint = CONFIG.isTouch
    ? (state.active ? 'Tap twice to cycle • Tap to deactivate' : 'Tap to activate • Tap twice to cycle')
    : (state.active ? 'Double-click to cycle • Click to deactivate' : 'Click to activate • Double-click to cycle');
  el.hint.textContent = hint;

  const showMode = state.active && state.colorMode > 0;
  el.modeIndicator.classList.toggle('visible', showMode);
  if (showMode) {
    el.modeIndicator.textContent = `◆ ${getColorName(state.colorMode).toUpperCase()}`;
  }
};

const applyState = () => {
  updateClasses();
  updateUI();
